    public static Field getField(Class<?> cls, String name) {
        for (Field field : cls.getDeclaredFields()) {
            if (!field.isAccessible()) {
                field.setAccessible(true);
            }
            if (field.getName().equals(name)) {
                return field;
            }
        }
        return null;
    }

    public static Object getFieldValue(Class<?> cls, Object obj, String name) {
        try {
            Field f = getField(cls, name);
            return f.get(obj);
        } catch (Exception ex) {
            ex.printStackTrace();
            return null;
        }
    }

    public static void setFieldValue(Class<?> cls, Object obj, String name, Object value) {
        System.out.println("setFieldValue" + cls + obj + name + value);
        if (name != null) {
            try {
                Field f = getField(cls, name);
                f.setAccessible(true);
                f.set(obj, value);
            } catch (Exception ex) {
                ex.printStackTrace();
            }
        }
    }

    public static String getCPUABI() {
        if (CPUABI == null) {
            try {
                Process process = Runtime.getRuntime().exec("getprop ro.product.cpu.abi");
                InputStreamReader ir = new InputStreamReader(process.getInputStream());
                BufferedReader input = new BufferedReader(ir);
                String abi = input.readLine();
                if (abi.contains("x86")) {
                    CPUABI = "x86";
                } else {
                    CPUABI = "arm";
                }
            } catch (Exception e) {
                CPUABI = "arm";
            }
            return CPUABI;
        }
        return CPUABI;
    }
